<?php require 'config.php';$id=(int)($_GET['id']??0);$s=$pdo->prepare('SELECT m.*,c.name category_name,c.icon FROM medicines m JOIN categories c ON c.id=m.category_id WHERE m.id=?');$s->execute([$id]);$p=$s->fetch();if(!$p){http_response_code(404);$title='Not found';require 'includes/header.php';echo '<div class="empty"><h2>Product not found</h2><a class="btn" href="/MediHome/medicines.php">Back to catalog</a></div>';require 'includes/footer.php';exit;}$related=$pdo->prepare('SELECT m.*,c.name category_name FROM medicines m JOIN categories c ON c.id=m.category_id WHERE m.category_id=? AND m.id<>? LIMIT 4');$related->execute([$p['category_id'],$id]);$relatedProducts=$related->fetchAll();$discount=(!empty($p['old_price'])&&(float)$p['old_price']>(float)$p['price'])?round((1-(float)$p['price']/(float)$p['old_price'])*100):0;$title=$p['name'].' | MediHome';require 'includes/header.php';?>
<div class="breadcrumbs"><a href="/MediHome/">Home</a> / <a href="/MediHome/category.php?id=<?=(int)$p['category_id']?>"><?=e($p['category_name'])?></a> / <?=e($p['name'])?></div><div class="detailgrid product-detail"><div class="detailart"><?php if($p['image_url']):?><img src="<?=e($p['image_url'])?>" alt="<?=e($p['name'])?>"><?php else:?>💊<?php endif;?></div><div class="detail"><span class="eyebrow"><?=e($p['icon'].' '.$p['category_name'])?></span><h1 class="product-detail-title"><?=e($p['name'])?></h1><p><?=e($p['description'])?></p><div class="detail-price-row"><h2><?=money($p['price'])?></h2><?php if($discount):?><span class="offer-badge large"><?=$discount?>% OFF</span><?php endif;?></div><?php if(!empty($p['old_price'])):?><p class="detail-old-price"><del><?=money($p['old_price'])?></del> <span>Offer price</span></p><?php endif;?><div class="detail-points"><span>✓ <?= (int)$p['stock']>0?'In stock':'Currently unavailable'?></span><span>✓ Easy cart and checkout</span><span>✓ Order history after login</span></div><?php if($p['prescription_required']):?><div class="notice">Prescription-required demo flag. Real pharmacies must verify valid prescriptions before dispensing.</div><?php endif;?><?php if((int)$p['stock']>0):?><form class="detail-add" method="post" action="/MediHome/cart.php"><input type="hidden" name="action" value="add"><input type="hidden" name="medicine_id" value="<?=(int)$p['id']?>"><label for="quantity">Quantity</label><input id="quantity" class="input" type="number" name="quantity" min="1" max="<?=(int)$p['stock']?>" value="1"><button class="btn" type="submit">Add to cart · <?=money($p['price'])?></button></form><?php endif;?><div class="notice product-note"><strong>Health information:</strong> Read the package label and product instructions carefully. Consult a qualified healthcare professional for medical advice.</div></div></div>
<section class="section"><div class="sectionhead"><div><span class="eyebrow">Keep exploring</span><h2>More in <?=e($p['category_name'])?></h2></div><a href="/MediHome/category.php?id=<?=(int)$p['category_id']?>">View category →</a></div><?php if($relatedProducts):?><div class="products"><?php foreach($relatedProducts as $p) require 'includes/card.php';?></div><?php else:?><p>More products will appear here as the catalog grows.</p><?php endif;?></section><?php require 'includes/footer.php';?>